#include<bits/stdc++.h>
#define ll long long
using namespace std;
const int MOD=1e9+7;
int n,m,k,f[1<<10],pc[1<<10];
ll g[1<<10];
void solve() {
	scanf("%d%d%d",&n,&m,&k);
	for(int i=1;i<n;++i) scanf("%*d");
	memset(f,0,sizeof(f)),memset(g,0,sizeof(g));
	if(!k) {
		ll s=1;
		for(int i=n;i<n+m;++i) s=s*(2*i-1)%MOD;
		return printf("%lld\n",s),void();
	}
	for(int i=1;i<(1<<k);++i) pc[i]=pc[i>>1]+(i&1);
	f[0]=1;
	for(int i=n;i<n+m;++i) {
		for(int s=0;s<(1<<k);++s) {
			if(s&1) g[s>>1]+=f[s];
			else {
				int z=i+pc[s],t=s>>1;
				g[t]+=1ll*f[s]*(2*z-1);
				for(int j=0;j<k;++j) if(!(t>>j&1)) g[t|(1<<j)]+=1ll*f[s]*(z-1);
			}
		}
		for(int s=0;s<(1<<k);++s) f[s]=g[s]%MOD,g[s]=0;
	}
	printf("%d\n",f[0]);
}
signed main() {
	int c,T; scanf("%d%d",&c,&T);
	while(T--) solve();
	return 0;
}
